 pub fn pacing_delay(low_streak_n: u32) -> Duration {
     let shift = low_streak_n.saturating_sub(1).min(31);
     let multiplier = 1u32 << shift;
     PACING_BASE_DELAY
         .checked_mul(multiplier)
         .unwrap_or(PACING_CAP_DELAY)
-        .min(PACING_CAP_DELAY)
 }

